import java.sql.*;
import java.util.*;

public class Main {
    static Integer balance(Connection c, int id) throws Exception {
        try (PreparedStatement p = c.prepareStatement("SELECT id, name, balance FROM users WHERE id = ?")) {
            p.setInt(1, id);
            try (ResultSet r = p.executeQuery()) {
                return r.next() ? r.getInt("balance") : null;
            }
        }
    }

    static void add(Connection c, int id, int amount) throws Exception {
        try (PreparedStatement p = c.prepareStatement("UPDATE users SET balance = balance + ? WHERE id = ?")) {
            p.setInt(1, amount);
            p.setInt(2, id);
            p.executeUpdate();
        }
    }

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int from = sc.nextInt(), to = sc.nextInt(), amount = sc.nextInt();
        try (Connection c = MiniJdbc.open()) {
            c.setAutoCommit(false);
            Integer a = balance(c, from), b = balance(c, to);
            if (a == null || b == null || amount <= 0 || a < amount) {
                c.rollback();
                System.out.println("failed");
                return;
            }
            add(c, from, - amount);
            add(c, to, amount);
            c.commit();
            System.out.println("from=" + (a - amount) + " to=" + (b + amount));
        }
    }
}
